package vn.rtr.aeris.field02;
import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import sun.misc.Unsafe;import org.json.JSONObject;
/** Exact frozen Activity recover() with JSON/time/fsync test adapters; not ART or power-loss durability. */
public class Recovery02Test{
 static int checks=0;static Unsafe unsafe;static Path root;static void ok(boolean b){if(!b)throw new AssertionError();checks++;}
 static Object instance(Path dir)throws Exception{Object a=unsafe.allocateInstance(ShellActivity.class);for(String k:new String[]{"root","journalHead","journalSeq"}){Field f=ShellActivity.class.getDeclaredField(k);f.setAccessible(true);f.set(a,k.equals("root")?dir.toFile():k.equals("journalHead")?"ROOT":Long.valueOf(0));}return a;}
 static void recover(Path p,boolean allowed)throws Exception{Object a=instance(p);Method m=ShellActivity.class.getDeclaredMethod("recover");m.setAccessible(true);try{m.invoke(a);if(!allowed)throw new AssertionError("must fail readonly");}catch(InvocationTargetException e){if(allowed)throw e;}checks++;}
 static Path fixture(String name,byte[]b)throws Exception{Path p=root.resolve(name);Files.createDirectory(p);Files.write(p.resolve("journal.jsonl"),b);return p;}
 static byte[] bytes(List<String>lines){return(String.join("\n",lines)+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 public static void main(String[]args)throws Exception{Field u=Unsafe.class.getDeclaredField("theUnsafe");u.setAccessible(true);unsafe=(Unsafe)u.get(null);root=Paths.get(args[0]);Files.createDirectory(root);List<String>lines=Files.readAllLines(Paths.get(args[1]));byte[]original=bytes(lines);Path nominal=fixture("nominal",original);recover(nominal,true);ok(Arrays.equals(original,Files.readAllBytes(nominal.resolve("journal.jsonl"))));Path pending=fixture("pending-prefix",bytes(lines.subList(0,9)));recover(pending,true);List<String>after=Files.readAllLines(pending.resolve("journal.jsonl"));ok(after.size()==10);JSONObject e=new JSONObject(after.get(9)),r=new JSONObject(e.getString("body"));ok(r.getString("kind").equals("UNKNOWN_AFTER_RESTART"));ok(r.getJSONObject("data").getString("id").equals("6bf3584c-1187-4bef-9c60-18d77fbf775f"));byte[]once=Files.readAllBytes(pending.resolve("journal.jsonl"));recover(pending,true);ok(Arrays.equals(once,Files.readAllBytes(pending.resolve("journal.jsonl"))));byte[]tail=Arrays.copyOf(original,original.length-1);Path torn=fixture("torn",tail);recover(torn,false);ok(Arrays.equals(tail,Files.readAllBytes(torn.resolve("journal.jsonl"))));List<String>tampered=new ArrayList<>(lines);tampered.set(0,lines.get(0).replace("MIRROR_COMMITTED","MIRROR_TAMPERED"));Path bad=fixture("tamper",bytes(tampered));recover(bad,false);ok(Arrays.equals(bytes(tampered),Files.readAllBytes(bad.resolve("journal.jsonl"))));List<String>reorder=new ArrayList<>(lines);Collections.swap(reorder,0,1);Path out=fixture("reordered",bytes(reorder));recover(out,false);ok(Arrays.equals(bytes(reorder),Files.readAllBytes(out.resolve("journal.jsonl"))));Path quota=fixture("over-byte-bound",new byte[1024*1024+1]);recover(quota,false);ok(Files.size(quota.resolve("journal.jsonl"))==1024*1024+1);System.out.println("{\"status\":\"PASS\",\"checks\":"+checks+",\"scope\":\"EXACT_FROZEN_RECOVER_HOST_JVM_JSON_TIME_FSYNC_ADAPTERS_NOT_ART_OR_DURABILITY\"}");}
}
